CREATE TABLE insights_activity (workspace_id TEXT NOT NULL, source TEXT NOT NULL, sequence INTEGER NOT NULL, event_id TEXT NOT NULL, entity_id TEXT NOT NULL, aggregate_version INTEGER NOT NULL, type TEXT NOT NULL, actor_id TEXT NOT NULL, client_id TEXT, occurred_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,source,sequence), UNIQUE(workspace_id,source,event_id));
CREATE INDEX insights_activity_time ON insights_activity(workspace_id,occurred_at DESC,source,sequence DESC);
CREATE TABLE insights_metrics (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, calculated_at INTEGER NOT NULL, todo INTEGER NOT NULL, in_progress INTEGER NOT NULL, done INTEGER NOT NULL, active_leases INTEGER NOT NULL, active_sessions INTEGER NOT NULL, PRIMARY KEY(workspace_id,project_id));
CREATE TABLE insights_subscriptions (workspace_id TEXT NOT NULL, principal_id TEXT NOT NULL, issue_id TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(workspace_id,principal_id,issue_id));
CREATE TABLE insights_notifications (workspace_id TEXT NOT NULL, principal_id TEXT NOT NULL, id TEXT NOT NULL, issue_id TEXT NOT NULL, kind TEXT NOT NULL, occurred_at INTEGER NOT NULL, version INTEGER NOT NULL CHECK(version>0), read INTEGER NOT NULL CHECK(read IN (0,1)), PRIMARY KEY(workspace_id,principal_id,id));
CREATE INDEX insights_notification_principal ON insights_notifications(workspace_id,principal_id,occurred_at DESC,id);
CREATE TABLE insights_cursors (workspace_id TEXT NOT NULL, source TEXT NOT NULL, sequence INTEGER NOT NULL, consumed_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,source));
CREATE TABLE insights_receipts (workspace_id TEXT NOT NULL, principal_id TEXT NOT NULL, operation_id TEXT NOT NULL, fingerprint TEXT NOT NULL, result_id TEXT NOT NULL, result_version INTEGER NOT NULL, active INTEGER, PRIMARY KEY(workspace_id,principal_id,operation_id));
CREATE TABLE insights_guards (workspace_id TEXT NOT NULL, id TEXT NOT NULL, changed INTEGER NOT NULL CHECK(changed=1), PRIMARY KEY(workspace_id,id));
